signature.advancedArgs:
{
  "type": "object",
  "properties": {
    "roundingPatternName": {
      "type": "string",
      "description": "The name of the rounding pattern (e.g., 'Beacon')"
    },
    "pattern": {
      "type": "string",
      "enum": [
        "General",
        "Range"
      ],
      "description": "The rounding pattern type"
    },
    "method": {
      "type": "string",
      "enum": [
        "1",
        "2",
        "3"
      ],
      "description": "Specifies the rounding method: Roundup (1), RoundDown (2), or Nearest (3). Only these values are accepted.",
      "examples": [
        "1",
        "2",
        "3"
      ]
    },
    "numVal": {
      "type": "string",
      "description": "The rounding value time (used in General pattern) if the change the genral compulsary take this value ask user consent and does not take user special characters ",
      "pattern": "^\\d{2}:\\d{2}$"
    },
    "numFrom": {
      "type": "string",
      "description": "The start time of the range (used in Range pattern) Range value must be a value between From and To values and must not be the same value and does not take user special characters.",
      "pattern": "^\\d{2}:\\d{2}$"
    },
    "numTo": {
      "type": "string",
      "description": "The end time of the range (used in Range pattern) Range value must be a value between From and To values and must not be the same value and does not take user special characters.",
      "pattern": "^\\d{2}:\\d{2}$"
    },
    "textnumValue": {
      "type": "string",
      "description": "The value applied for the range (used in Range pattern) and does not take user special characters and be text numValue in between start time of the range to end time of the range",
      "pattern": "^\\d{2}:\\d{2}$"
    }
  },
  "required": [
    "roundingPatternName",
    "pattern"
  ],
  "if": {
    "properties": {
      "pattern": {
        "const": "General"
      }
    }
  },
  "then": {
    "required": [
      "method",
      "numVal"
    ]
  },
  "else": {
    "required": [
      "numFrom",
      "numTo",
      "numValue"
    ]
  }
}

